import{z as A,x as s,o as t,c as d,q as n,j as i,D as E,d as e,s as B,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"正则化组合","description":"","frontmatter":{"title":"正则化组合","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-regularized.md","filePath":"quant/pf-regularized.md","lastUpdated":1791063341000}'),m={name:"quant/pf-regularized.md"};function p(h,a,u,D,f,_){const r=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="正则化组合" tabindex="-1">正则化组合 <a class="header-anchor" href="#正则化组合" aria-label="Permalink to &quot;正则化组合&quot;">​</a></h1><div class="epigraph"><p>正则化是对自己估计能力的不信任，明码标价地写进目标函数；约束与罚项是同一枚硬币的两面，差别只在记账科目。</p><footer>—— 据 Jagannathan and Ma, Journal of Finance, 2003；Brodie, Daubechies, De Mol, Giannone and Loris, PNAS, 2009 整理</footer></div><p><a href="/quant/pf-optimizer-numerics">上一课</a>把数值层钉住：尺度与预条件、秩与条件数、KKT 与扰动验收——扰动测试不过关的解，说明目标函数对输入过敏。缺口在上一层：与其等病态解出来再收拾，不如先把不信任声明进目标。本课把组合问题的正则化谱系一次排清：罚在权重上、罚在协方差上、罚在结构上，以及约束与罚项的对偶关系。后课的黑盒与策略维度都默认这套词汇。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/quant/markowitz">Markowitz</a> 的无约束解在估计误差面前是放大器——上一课的平坦谷底与顶点跳变就是症状。对策有两族：事后修输入（对 \\(\\Sigma\\) 收缩），事前修目标（加罚项或约束）。<span class="marginnote">「正则化」就是给优化加一条「别太信你的估计」的惩罚项，让解在「贴合数据」与「保持简单」之间折中。直觉类比：答题不只求贴合材料，还要写得简洁有条理——罚项就是那个「简洁分」，防止你把噪声当规律抄进答案。</span>都不做，错法自然：误差被放大成角点仓位；反过来做歪了也错——把正则强度 \\(\\lambda\\) 当玄学，挑到样本内回测最亮为止，等于把多重检验从信号层原样搬到权重层，<a href="/quant/multiple-testing-factors">多重检验与 p-hacking</a> 的账单照收不误。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把「不信任」逐层写进目标函数：权重层加罚、协方差层换估计、可行层加约束——三层的数学身份不同，起到的作用同源。每层给出代表文献与实现口径，约束与罚项的对偶关系留到机制一节对账。挑层的次序从便宜到贵：约束与收缩先上，稀疏罚按需再加；上一课的扰动验收在加了罚项之后照跑不误。</p><h3 id="三层罚项" tabindex="-1">三层罚项 <a class="header-anchor" href="#三层罚项" aria-label="Permalink to &quot;三层罚项&quot;">​</a></h3><p>罚在权重上：\\(\\min_w\\; w^\\top\\Sigma w-\\gamma\\,\\mu^\\top w+\\lambda_2\\lVert w\\rVert_2^2+\\lambda_1\\lVert w\\rVert_1\\)。\\(\\ell_2\\) 把解往等权方向收，\\(\\ell_1\\) 直接产生稀疏组合；<span class="marginnote">数字实例区分两种罚：\\(\\ell_2\\) 罚权重的平方和，30% 仓位的罚是 0.09，于是它把大仓位往回拉、每个名字都留一点；\\(\\ell_1\\) 罚绝对值之和，同样 30% 的罚是 0.3，小权重干脆被压成零——这就是「\\(\\ell_1\\) 出稀疏、\\(\\ell_2\\) 出普遍收缩」的算术来源。</span>Brodie 等（2009）把 \\(\\ell_1\\) 稀疏性同时读作正则与成本控制——持有的名字少了，监督与换手都轻。这个对照的极端是 \\(1/N\\)：DeMiguel、Garlappi 与 Uppal（2009）的系统比较显示，等权在样本外方差与夏普上常常不输优化组合——正则化不足的 Markowitz，输给最笨的正则。罚在协方差上：<a href="/quant/ledoit-wolf">Ledoit-Wolf 收缩</a>把 \\(\\Sigma\\) 拉向结构化目标，是估计层的正则，<a href="/quant/cov-shrinkage">估计误差与收缩</a>写了机制。罚在结构上：严格因子结构 \\(\\Sigma=BFB^\\top+\\Delta\\) 用低维载荷换掉满矩阵的自由度，选择逻辑见<a href="/quant/factor-vs-sample-cov">因子协方差 vs 样本</a>。约束即正则：Jagannathan 与 Ma（2003）证明，非负约束在总体层面等价于对 \\(\\Sigma\\) 的一种收缩，「错误」的约束反而降低样本外方差——制度通过可行集完成了统计收缩，细节见<a href="/quant/long-short-constraints">多空与多头约束</a>。</p>',9)),(t(),i(o,null,{default:E(()=>[B(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIT%5B%22%E6%8B%9F%E5%90%88%E9%A1%B9%EF%BC%9Aw'Sigma%20w%20-%20gamma%20mu'w%22%5D%20--%3E%20L2%5B%22L2%EF%BC%9A%E5%90%91%E7%AD%89%E6%9D%83%E6%94%B6%E7%BC%A9%22%5D%0A%20%20FIT%20--%3E%20L1%5B%22L1%EF%BC%9A%E7%A8%80%E7%96%8F%E6%8C%81%E4%BB%93%22%5D%0A%20%20FIT%20--%3E%20COV%5B%22Sigma%20%E5%B1%82%EF%BC%9A%E6%94%B6%E7%BC%A9%E4%B8%8E%E5%9B%A0%E5%AD%90%E7%BB%93%E6%9E%84%22%5D%0A%20%20FIT%20--%3E%20CON%5B%22%E7%BA%A6%E6%9D%9F%EF%BC%9A%E9%9D%9E%E8%B4%9F%E4%B8%8E%E6%9A%B4%E9%9C%B2%E4%B8%8A%E9%99%90%22%5D%0A%20%20L2%20--%3E%20W%5B%22%E8%A7%A3%E7%9A%84%E5%BD%A2%E7%8A%B6%E4%B8%8E%E6%8D%A2%E6%89%8B%22%5D%0A%20%20L1%20--%3E%20W%0A%20%20COV%20--%3E%20W%0A%20%20CON%20--%3E%20W%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[e("偏差–方差的交换在组合语境里换了名字：正则化引入的「偏差」其实是政策——不押单一名字、不满仓单一因子，是章程本来就想要的东西。两种实现的接口由拉格朗日对偶给出：约束的影子价格就是罚系数，\\(\\lambda\\) 变动等价于可行集伸缩；实现上可以互换，报告时必须写清用了哪种，因为等价依赖特定的 \\(\\lambda\\) 映射与问题数据，审计口径不能两套混着讲。\\(\\lambda\\) 本身的纪律只有两条路：按样本外风险用滚动验证挑，或按等效约束的政策值反推——唯独不能按样本内收益挑，否则下一课黑盒搜索的过拟合机制会提前在 \\(\\lambda\\) 这一根轴上发生。还有一层工程红利：稀疏解换手少，与"),l("a",{href:"/quant/turnover-penalty"},"换手惩罚"),e("的成本口径天然咬合。")],-1)),(t(),i(o,null,{default:E(()=>[B(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20L0%5B%22lambda%20%E7%BA%A6%E7%AD%89%E4%BA%8E%200%22%5D%20--%3E%20A%5B%22%E8%BF%91%E4%BC%BC%E6%97%A0%E7%BA%A6%E6%9D%9F%E8%A7%A3%EF%BC%9A%E8%A7%92%E7%82%B9%E4%B8%8E%E9%AB%98%E6%9D%A0%E6%9D%86%22%5D%0A%20%20A%20--%3E%20B%5B%22lambda%20%E6%B8%90%E5%A2%9E%EF%BC%9A%E6%9D%83%E9%87%8D%E5%90%91%E4%B8%AD%E9%97%B4%E6%94%B6%E7%BC%A9%22%5D%0A%20%20B%20--%3E%20C%5B%22L2%20%E4%B8%BB%E5%AF%BC%EF%BC%9A%E6%95%B4%E4%BD%93%E5%81%8F%E5%90%91%E7%AD%89%E6%9D%83%22%5D%0A%20%20B%20--%3E%20D%5B%22L1%20%E4%B8%BB%E5%AF%BC%EF%BC%9A%E6%8C%81%E4%BB%93%E5%90%8D%E5%8D%95%E5%8F%98%E7%9F%AD%22%5D%0A%20%20C%20--%3E%20E%5B%22lambda%20%E8%BF%87%E5%A4%A7%EF%BC%9A%E8%B6%8B%E5%90%91%E9%9B%B6%E4%BB%93%E6%88%96%E7%BA%AF%E7%AD%89%E6%9D%83%22%5D%0A%20%20D%20--%3E%20E%0A%20%20E%20--%3E%20F%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%E9%A3%8E%E9%99%A9%E9%9A%8F%20lambda%20%E5%91%88%20U%20%E5%BD%A2%EF%BC%8C%E5%8F%96%E8%B0%B7%E5%BA%95%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">「影子价格」是约束松动一格能换来多少目标改善：某名字非负约束的影子价格若为 0.02，意味着允许它做空 1%，最优目标约改善 0.02。为什么重要：影子价格正是罚系数 \\(\\lambda\\) 的对偶读数——看懂这一点，「约束版」与「罚项版」就不再像两套魔法。</span></p><p><span class="marginnote">Jagannathan–Ma 的反直觉量级：非负约束隐含的收缩幅度，与专门设计的收缩估计同数量级——制度里「错」的约束，在总体层面买到了「对」的稳健。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲收缩公式的推导；不展开风险平价那一族「不逆满 \\(\\Sigma\\)」的配置器——<a href="/quant/erc-mrc">ERC 与边际风险贡献</a>与<a href="/quant/hrp-linkage">HRP 联结与准对角化</a>是同一不信任思想的另外两条路，此处只点名。\\(\\ell_1\\) 带来的稀疏解对特征选择敏感，删掉一只名字解可能重排，扰动验收（上一课）照样适用。基数约束、手数取整与固定成本这类凸化失败的目标，罚项救不了，是下一课黑盒优化器的地盘。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正则化的三层：罚权重（\\(\\ell_1\\) 稀疏、\\(\\ell_2\\) 收缩）、罚协方差（收缩、因子结构）、约束当正则（Jagannathan–Ma）。</li><li>约束与罚项由对偶等价；实现可互换，报告口径要唯一。</li><li>\\(1/N\\) 是天然的对照基线：优化组合赢不了等权，说明正则化没做够或 \\(\\Sigma\\) 太糟。</li><li>\\(\\lambda\\) 按样本外风险或政策值定，不按样本内收益定；稀疏解的红利之一是成本链上的低换手。</li><li>出处：Jagannathan &amp; Ma, <em>JF</em>, 2003；Brodie 等, <em>PNAS</em>, 2009；DeMiguel, Garlappi &amp; Uppal, <em>RFS</em>, 2009；Ledoit &amp; Wolf, 2004。</li></ul>',6))])}const C=A(m,[["render",p]]);export{g as __pageData,C as default};
